window.NUT_I18N = {"locale":"en","lang":"en","dir":"ltr","strings":{"ui.site.name":"Case in a Nutshell","ui.close":"Close","ui.check":"Check","ui.toast.fact":"New fact: {title}","ui.msg.enter.hall":"The hallway. A log and a monitor sit on the desk, and the key board hangs beside it.","ui.msg.enter.bedroom":"Back in Elias's bedroom.","ui.msg.start":"You step into the scene. Tap anything that looks interesting. The moments bar under the picture shows this same room at other times.","ui.msg.back":"Welcome back. Your notebook is just as you left it.","ui.msg.reset":"The case started over.","ui.msg.lampPast":"The bedside lamp is on in this account.","ui.msg.lampOn":"The lamp is on. The drawing on the wall is easier to read now.","ui.msg.lampOff":"The lamp is off.","ui.msg.clockPast":"The clock reads {time} and is running.","ui.msg.boxPast":"A brass music box on the dresser. Its lock is intact.","ui.msg.boxOpen":"The box is open and there is nothing left inside.","ui.diff.count":"Differences found: {n} of {total}","ui.diff.need":" (at least {need} needed)","ui.diff.on":"Difference finder is on. Tap anything that differs between Viktor's account and the scene. Use the moments bar to switch between the two.","ui.diff.none":"You see no difference here between these two moments.","ui.intro.title":"Case {no}: {title}","ui.intro.found":"Found: {when}","ui.intro.tip":"Search the rooms, compare the moments, and everything you work out is collected in your notebook.","ui.intro.start":"Start investigating","ui.clock.title":"The bedside clock","ui.clock.stopped":"The crown is pulled out and the clock has stopped. The hands are frozen at {time}.","ui.clock.running":"The clock is running.","ui.clock.push":"Push the crown in","ui.clock.missed":"You missed someone.","ui.docs.title":"Hallway documents","ui.docs.seeAll":"Open every document tab, then you can answer.","ui.lock.up":"Increase digit {n}","ui.lock.down":"Decrease digit {n}","ui.lock.try":"Try it","ui.lock.wrong":"The lock won't open. Count again.","ui.letter.title":"Inside the box","ui.nb.title":"Fact notebook","ui.nb.progress":"{n} of {total} main facts found","ui.nb.empty":"Your notebook is empty. Each puzzle adds a fact.","ui.nb.reset":"Restart this case","ui.nb.confirm":"Erase your progress on this case?","ui.sus.title":"Victim and suspects","ui.sus.found":"Found: {when}","ui.sus.motive":"Apparent motive: {x}","ui.sus.room":"See the room as they told it","ui.acc.title":"Accusation board","ui.acc.locked":"To accuse someone you need {needs}.","ui.acc.unknown":"Not found yet","ui.acc.solved":"This case is closed.","ui.acc.view":"See the verdict","ui.acc.intro":"Using the facts in your notebook, choose all three parts.","ui.acc.submit":"Make the accusation","ui.acc.pickAll":"Choose an answer for all three parts.","ui.acc.contradicts":"{part} contradicts the fact “{fact}”: {why}","ui.acc.missing":"{part} Your notebook has no fact yet that rules this out. Keep searching.","ui.hint.declined":"Marmalade shrugs. Maybe later.","ui.hint.say":"Marmalade the cat leans in and whispers: “{text}”","ui.end.title":"Case closed","ui.end.truth":"What really happened","ui.end.share":"Case in a Nutshell · {title}\n{stars} · {min} min · {tries} wrong accusations","ui.end.shareLabel":"Text to share","ui.end.copy":"Copy result","ui.end.copied":"Copied.","ui.end.manual":"Select the text and copy it.","ui.end.stay":"Keep looking around","ui.end.again":"Start over","ui.end.board":"Case board","ui.door.to":"Door to {name}","ui.door.locked":"This door is locked.","ui.map.title":"Map","ui.map.here":"You are here","ui.map.go":"Go","ui.map.unknown":"Not visited yet","ui.map.tip":"Tap a room to go there. Rooms you have not seen are only open from a room next to them.","ui.menu.button":"Menu","ui.menu.title":"Menu","ui.menu.close":"Close","ui.menu.cases":"Cases","ui.menu.board":"All cases","ui.menu.language":"Language","ui.menu.font":"Font style","ui.menu.fontMixed":"Mixed","ui.menu.fontPixel":"All pixel","ui.menu.fontClean":"Clean","ui.menu.size":"Text size","ui.menu.sizeS":"Small","ui.menu.sizeM":"Medium","ui.menu.sizeL":"Large","ui.menu.motion":"Motion","ui.menu.motionAuto":"Automatic","ui.menu.motionReduce":"Reduced","ui.menu.sample":"Sample: the quick brown fox jumps over the lazy dog.","obj.sofa.label":"Sofa","obj.sofa.say":"A comfortable sofa. The cushions have a dent where someone always sits.","obj.armchair.label":"Armchair","obj.armchair.say":"A small armchair, a bit too good for sitting still.","obj.coffeetable.label":"Coffee table","obj.coffeetable.say":"A low table with a book and a mug.","obj.tvunit.label":"TV unit","obj.tvunit.say":"A television on a low cabinet. The screen is dark.","obj.tv.label":"Television","obj.tv.say":"A television. The screen is dark.","obj.bookshelf.label":"Bookshelf","obj.bookshelf.say":"Books of every colour, shelved with more love than order.","obj.floorlamp.label":"Floor lamp","obj.floorlamp.say":"A tall floor lamp.","obj.kcounter.label":"Kitchen counter","obj.kcounter.say":"A kitchen counter with cupboards underneath.","obj.fridge.label":"Refrigerator","obj.fridge.say":"A refrigerator humming to itself.","obj.table.label":"Table","obj.table.say":"A small table, laid for two.","obj.chair.label":"Chair","obj.chair.say":"A wooden chair.","obj.toilet.label":"Toilet","obj.toilet.say":"A toilet. Nothing to see here.","obj.tub.label":"Bathtub","obj.tub.say":"A bathtub, filled with a little water.","obj.basin.label":"Washbasin","obj.basin.say":"A washbasin with a dripping tap.","obj.shelfunit.label":"Shelving","obj.shelfunit.say":"Metal shelving packed with boxes and jars.","obj.boxes.label":"Cardboard boxes","obj.boxes.say":"Cardboard boxes, taped shut.","obj.crates.label":"Crates","obj.crates.say":"Wooden crates, nailed shut.","obj.barrel.label":"Barrel","obj.barrel.say":"An old barrel. It smells of apples.","obj.ladder.label":"Ladder","obj.ladder.say":"A wooden ladder leaning on the wall.","obj.workbench.label":"Workbench","obj.workbench.say":"A workbench with a few tools.","obj.boiler.label":"Boiler","obj.boiler.say":"The building boiler. It ticks and gurgles.","obj.bin.label":"Bin","obj.bin.say":"A rubbish bin.","obj.tree.label":"Tree","obj.tree.say":"A tree. Its fruit is small, orange and a little sour.","obj.bush.label":"Bush","obj.bush.say":"A flowering bush.","obj.bench.label":"Bench","obj.bench.say":"A wooden bench.","obj.tap.label":"Tap","obj.tap.say":"An outdoor tap, dripping.","obj.bucket.label":"Bucket","obj.bucket.say":"A bucket under the tap.","obj.flowerbed.label":"Flowerbed","obj.flowerbed.say":"A small flowerbed.","obj.car.label":"Car","obj.car.say":"A parked car.","obj.pillar.label":"Pillar","obj.pillar.say":"A concrete pillar with hazard stripes.","obj.stairs.label":"Stairs","obj.stairs.say":"A flight of stairs.","obj.plant.label":"Plant","obj.plant.say":"A houseplant.","obj.pouf.label":"Pouf","obj.pouf.say":"A blue pouf with a friendly face.","obj.bed.label":"Bed","obj.bed.say":"A neatly made bed.","obj.nightstand.label":"Nightstand","obj.nightstand.say":"A small nightstand.","obj.dresser.label":"Dresser","obj.dresser.say":"A dresser with four drawers.","obj.desk.label":"Reception desk","obj.desk.say":"A reception desk.","obj.cat.label":"Cat","obj.cat.say":"A cat, watching.","obj.rug.label":"Rug","obj.rug.say":"A rug.","obj.window.label":"Window","obj.window.say":"A window.","obj.picture.label":"Picture","obj.picture.say":"A framed picture.","obj.mirror.label":"Mirror","obj.mirror.say":"A mirror.","obj.mailboxes.label":"Mailboxes","obj.mailboxes.say":"The mailboxes.","obj.panel.label":"Button panel","obj.panel.say":"A button panel.","obj.vent.label":"Vent","obj.vent.say":"A vent that breathes cold air.","obj.sign.label":"Sign","obj.sign.say":"A building sign.","obj.shower.label":"Shower","obj.shower.say":"A shower behind a striped curtain.","obj.officedesk.label":"Office desk","obj.officedesk.say":"A desk with a computer and a red mug.","obj.computer.label":"Computer","obj.computer.say":"A computer, asleep.","obj.cabinet.label":"Filing cabinet","obj.cabinet.say":"A grey filing cabinet. The drawers are full.","obj.cooler.label":"Water cooler","obj.cooler.say":"A water cooler. It gurgles.","obj.printer.label":"Printer","obj.printer.say":"A printer with a little paper in the tray.","obj.lounger.label":"Sun lounger","obj.lounger.say":"A sun lounger, warm from the sun.","obj.floatring.label":"Pool float","obj.floatring.say":"A flamingo pool float. Nobody is on it.","obj.poolladder.label":"Pool ladder","obj.poolladder.say":"A metal pool ladder.","obj.planter.label":"Planter","obj.planter.say":"A big plant in a clay pot.","obj.bookpile.label":"Pile of books","obj.bookpile.say":"A pile of books, waiting to be shelved.","obj.nook.label":"Reading nook","obj.nook.say":"A reading nook with a few cushions.","obj.hangplant.label":"Hanging plant","obj.hangplant.say":"A hanging plant.","obj.rail.label":"Handrail","obj.rail.say":"A steel handrail.","obj.door.label":"Door","obj.door.say":"A door.","obj.pillow.label":"Pillows","obj.pillow.say":"The pillows are soft.","obj.slippers.label":"Slippers","obj.slippers.say":"A pair of felt slippers.","obj.camerapost.label":"Camera post","obj.camerapost.say":"A post with a camera that watches the yard.","ui.door.lockedTag":"(locked)","ui.toast.item":"You found: {title}","ui.nb.items":"Things you carry","obj.chalk.label":"Chalk outline","obj.chalk.say":"A chalk outline on the floor.","obj.plantbench.label":"Plant bench","obj.plantbench.say":"A long bench of potted orchids and ferns, labelled in careful handwriting.","obj.wateringcan.label":"Watering can","obj.wateringcan.say":"A tin watering can.","ui.lock.clear":"Clear","ui.wire.red":"Red wire","ui.wire.blue":"Blue wire","ui.wire.green":"Green wire","ui.wire.yellow":"Yellow wire","ui.wire.white":"White wire","ui.sym.square":"Square","ui.sym.circle":"Circle","ui.sym.triangle":"Triangle","ui.sym.cross":"Cross","ui.sym.star":"Star","ui.talk.title":"Interview","ui.talk.testimony":"Testimony","ui.talk.noted":"Noted: {text}","ui.talk.leave":"End interview","ui.talk.present":"Present evidence","ui.talk.pick":"Pick a fact from your notebook.","ui.talk.noContra":"That doesn't contradict what I said.","ui.talk.locked":"Not yet. You don't know enough to ask.","ui.talk.notes":"Testimony","ui.end.confession":"Confession","ui.needs.default":"You don't know enough yet.","ui.lock.cooldown":"The lock is stiff. Wait a moment.","ui.lock.print":"Print","ui.lock.hour":"Hour","ui.lock.minute":"Minute","ui.lock.stamp":"Stamp {n}","ui.jigsaw.rotate":"Rotate","ui.jigsaw.test":"Try the fit","ui.jigsaw.fits":"It fits.","ui.jigsaw.no":"It doesn't fit.","ui.map.group.court":"Orange Grove Court","ui.map.group.hq":"Police HQ","ui.map.group.hotel":"Hotel Lyra","ui.map.room.hq":"Detective's office","ui.map.room.interrog":"Interview room","ui.map.room.hlobby":"Hotel lobby and bar","ui.map.room.hcorr":"Second-floor corridor","ui.map.room.room214":"Room 214","ui.jigsaw.move":"Move the page with the arrow keys or drag it.","ui.talk.suspectBtn":"Talk to {name}","ui.talk.confrontBtn":"Question {name}","ui.talk.claim":"Claim {n}","ui.talk.broken":"Broken","ui.talk.read":"Read","ui.talk.none":"No interview is open yet.","ui.timeline.label":"Timeline","ui.spot.found":"Differences found: {n} of {total}","ui.spot.tip":"Tap the place on either signature where they differ.","ui.cork.title":"Case board","ui.cork.empty":"Nothing pinned up yet.","case.title":"Monday, 9 A.M.","case.tagline":"A ceramic artist is found dead the day before she was due to sign her divorce settlement. Everybody has an alibi, and one of them is made of receipts.","case.building":"Orange Grove Court","case.unit":"Apartment 7","case.foundAt":"07:52","room.living":"Living room","room.lobby":"Lobby","room.basement":"Basement","intro.0":"Model No. 2. Orange Grove Court, Apartment 7.","intro.1":"Priya Raman, a ceramic artist aged 44, was found dead on her living-room floor at 07:52 on Sunday morning. She had moved into Apartment 7 six weeks earlier, after the divorce papers were drawn up. On Monday at 9 o'clock she was due to sign the settlement that splits the studio, the kiln and the money. Nothing is forced, nothing valuable is gone, and there are two cups on the table.","intro.2":"Four people have an account of their Saturday evening. Read the building's records, compare the room at different times, and say who did it, how, and why. People can lie. Meters, cameras and cups do not.","victim.name":"Priya Raman","victim.role":"Ceramic artist, 44","suspect.daniel.name":"Daniel Hart","suspect.daniel.role":"Priya's ex-husband and studio partner, 47","suspect.daniel.statement":"I was at the Hotel Lyra, an hour's drive from here, from 20:35 on Saturday until breakfast on Sunday. I had a drink at the bar around ten and went up to my room. I haven't been near Orange Grove Court since Priya moved in. The hotel will confirm all of it. I did not know she was dead until the police called.","suspect.daniel.hint":"The Monday signing","suspect.sofia.name":"Sofia Marin","suspect.sofia.role":"Daniel's partner, florist, 35","suspect.sofia.statement":"I came to see Priya at 18:55 to ask her to be reasonable about the settlement. We argued and I left at 19:25. Then Daniel and I drove to the Hotel Lyra for a weekend away. I never left it.","suspect.sofia.hint":"Jealousy, and a joint account with Daniel","suspect.noor.name":"Noor Haddad","suspect.noor.role":"Neighbour in Apartment 6, night nurse, 31","suspect.noor.statement":"I knocked at about 19:30 to ask her to stop firing the kiln at night. We were polite, mostly. I left for my shift at 19:41 and came home at 06:40 in the morning.","suspect.noor.hint":"Kiln noise, and a lease dispute","suspect.mateo.name":"Mateo Reyes","suspect.mateo.role":"Building caretaker, 52","suspect.mateo.statement":"I kept the front desk until 20:00. At 21:36 I went down to the basement for the boiler's annual service and I was there until a quarter to eleven. On Sunday at 07:52 I saw her door ajar and went in. I touched nothing.","suspect.mateo.hint":"A rent warning from Priya","moment.sofia.label":"Sofia","moment.sofia.caption":"Sofia's account, 19:10: the floor lamp is on, the settlement folder lies on the table beside Priya's tea, and the slippers are tidy by the door. Priya did not offer her a seat.","moment.noor.label":"Noor","moment.noor.caption":"Noor's account, 19:30: the tea is finished, two papers lie side by side beside a magnifier, the lamp is on. Priya told her the kiln stays.","moment.scene.label":"Scene","moment.scene.caption":"The discovery scene, 07:52, as the caretaker and the police found it.","diff.item.floorlamp":"Floor lamp: on in Noor's account, found off in the morning.","diff.item.slippers":"Slippers: tidy by the door in Noor's account. In the morning they are scattered.","diff.item.cup2":"A second cup: in Noor's account there is one cup. In the morning there are two.","diff.item.papers":"The settlement folder: on the table in Noor's account. In the morning it is gone.","observe.cup2":"A second cup, used. Priya made tea for a guest and sat down with them.","accuse.unlock":"all six key facts","verdict.line":"Daniel Hart forged Priya Raman's signature on a loan guarantee. When the bank's envelope reached her on Saturday, he went to take the folder back and built an alibi in case talking failed. Talking failed. He made that alibi out of things, a phone, a film and a bar tab, and left the one person who could spoil it, Sofia, to pay the tab for him.","verdict.thread":"Case closed. Under the lobby desk, Marmalade the cat has found a library card with a date stamped one week ahead and a note in tiny handwriting: “The last reading.”","verdict.next.title":"The Last Reading","verdict.next.note":"Coming soon","hot.living.cup.label":"Priya's cup","hot.living.cup.say":"A blue cup with dried tea. Priya's own.","hot.living.cup2.label":"Second cup","hot.living.cup2.say":"A second cup, used. Nobody drinks tea alone from two cups.","hot.living.papers.label":"Settlement folder","hot.living.papers.say":"A cream folder: the settlement for the studio, the kiln and the money, ready for Monday.","diff.note.chalk":"That is where Priya lay. It is a consequence of the evening, not a clue.","hot.living.chalk.label":"Chalk outline","hot.living.chalk.say":"The police chalk where Priya was found, between the sofa and the table.","fact.changed.title":"The folder is gone","fact.changed.text":"Between 19:30 and the morning the lamp went out, the slippers were kicked about, a second cup of tea appeared and the settlement folder vanished. Nothing else was taken: this was about Monday's signing, not a burglary.","fact.guest.title":"Two cups","cell.circ.lights":"Living room lights","cell.circ.kettle":"Kitchen kettle","cell.circ.tv":"Living room TV","cell.circ.lamp":"Floor lamp circuit","cell.circ.hall":"Hall light","cell.ev.on":"Switched on","cell.ev.short":"Cord pulled: circuit tripped","accuse.who.title":"Who?","accuse.how.title":"How?","accuse.why.title":"Why?","hot.basement.meter.label":"Electricity meter","hot.basement.meter.say":"The building's smart meter.","hot.basement.monitor.label":"Camera 2 monitor","hot.basement.monitor.say":"The basement camera.","fact.guest.text":"Priya made tea for a guest and sat down with them. She let whoever it was in at ten at night, and her note says she was willing to listen.","fact.window.text":"The meter log: kettle at 21:56, the TV off at 21:59, and at 22:04 the floor lamp's cord was pulled hard enough to trip the circuit. Nothing used power again. The attack was between 21:50 and 22:15.","fact.window.title":"The minute","fact.buzz.title":"A visitor without a fob","fact.buzz.text":"At 21:53 Priya buzzed someone in from her intercom. Noor and Mateo both have fobs, so they would never need buzzing in. The visitor was Sofia or Daniel.","fact.leave.title":"Six minutes slow","fact.leave.text":"The camera stamped the intercom blink at 21:47 and the log records the release at 21:53: the camera is six minutes slow. So the visitor left at 22:21, after 28 minutes inside, in a hurry with a roll of papers.","fact.figure.title":"Tall, hooded, in the rain","fact.figure.text":"The visitor was about 185 cm. Daniel, Mateo and Sofia in her heels all fit. Noor is far too short.","fact.boiler.title":"The caretaker in the basement","fact.boiler.text":"Camera 2 has Mateo at the boiler at 21:40, 22:04 and 22:20. The ten minutes between his statement and the sheet come after all that and change nothing. He was not upstairs at 22:04.","fact.paper.title":"A page from the Lyra","fact.paper.text":"A page of the Lyra's own guest paper was dropped in the lobby bin. The visitor came from the hotel. Daniel said he never went near this building, and Sofia said she never left the hotel.","fact.bar.title":"Who paid at the bar","fact.bar.text":"The 22:10 tab is on Daniel's card, but the bar camera shows Sofia paying with it and no Daniel anywhere. She had been sitting alone with two glasses since 21:35, at the Lyra, an hour away: she is cleared. Daniel's alibi is a phone in a room, a film and a tab: things. The cameras see him only at 20:35 and 07:20.","fact.door.title":"The side door","fact.door.text":"At 20:50 someone left the Lyra by the side door, which has no camera, and came back by it at 23:22. It was not Sofia, who was at the bar until 22:10. Daniel, who says he never left, had the time and the way.","fact.timing.title":"It fits to the minute","fact.timing.text":"The side door opened at 20:50 and again at 23:22: 152 minutes away. Driving there and back takes 120, which leaves at most 32 minutes at the building. The visitor stayed 28.","fact.torn.title":"A torn Gazette","fact.torn.text":"The soaked page fits the torn first page of room 214's Gazette. The page came from the room where Daniel and Sofia were staying.","fact.forgery.title":"The studio was pledged","fact.forgery.text":"The studio was pledged with a forged signature, and the money went to an account shared by Daniel and Sofia. Monday's visit to the bank would have exposed it.","fact.signature.title":"A signature that is not hers","fact.signature.text":"The signature on the guarantee is not Priya's: the leg of the R, the dot of the i and the pressure of the pen all differ from her own, and it lacks her potter's stamp.","fact.corner.title":"A blow on the table's corner","fact.corner.text":"One blow, consistent with a fall against the table's edge. No weapon was used. Whoever it was pushed her, then stayed half an hour.","observe.cornertable":"The corner of the table is scuffed and chipped, as if somebody hit it hard.","board.window.title":"The meter","board.window.ask":"The flat's power stops for good at one point. When was Priya attacked?","doc.window.meter.title":"Meter: Apartment 7","doc.window.meter.note":"The building's smart meter records every circuit of every flat, to the minute. Its clock is synced to the exchange.","doc.window.meter.col.0":"Time","doc.window.meter.col.1":"Circuit","doc.window.meter.col.2":"Event","doc.window.meter.foot":"The log is stored in the basement and cannot be edited from the flats.","cell.ev.kettle2":"Ran for 2 minutes","cell.ev.kettle3":"Ran for 3 minutes","cell.ev.onwall":"Switched on at the wall","cell.ev.offwall":"Switched off at the wall","board.window.opt.early":"Before 21:00","board.window.opt.early.wrong":"The kettle ran at 21:56 and the TV was switched off at 21:59. She was alive and hosting well after nine.","board.window.opt.evening":"Between 21:50 and 22:15","board.window.opt.late":"Around midnight","board.window.opt.late.wrong":"Nothing in the flat drew power after 22:04. Nobody was moving about in there at midnight.","board.window.opt.dawn":"Early on Sunday","board.window.opt.dawn.wrong":"The flat is silent from 22:04 until the caretaker switches on the hall light at 07:52.","board.buzz.title":"The front-door records","board.buzz.ask":"The 21:53 entry was released from inside Apartment 7. Select every suspect who would have needed to be buzzed in.","board.buzz.none":"Select at least one person. The log says the front door was released from an intercom.","board.buzz.wrong.daniel":"Daniel moved out long ago and has no fob. Someone has to buzz him in.","board.buzz.wrong.sofia":"Sofia does not live here and has no fob. The visitor log shows she had to be buzzed in at 18:55 too.","board.buzz.wrong.noor":"Noor lives in Apartment 6 and has a fob. Her last use is 19:41, on her way out. She would not ring Priya's intercom.","board.buzz.wrong.mateo":"Mateo has a fob and used it at the basement door at 21:36. He would not need Priya to let him in.","doc.buzz.visitors.title":"Visitor log","doc.buzz.visitors.note":"Written by hand at the front desk.","doc.buzz.visitors.col.0":"Name","doc.buzz.visitors.col.1":"In","doc.buzz.visitors.col.2":"Out","doc.buzz.visitors.col.3":"Remarks","doc.buzz.visitors.foot":"The desk is staffed until 20:00. After that the log is closed.","cell.who.courier":"Bank courier","cell.rem.courier":"Envelope for Apt 7, Guarantee Dept. Taken up by M.R.","cell.rem.sofia":"Very high heels (c. 12 cm). In a hurry.","doc.buzz.doors.title":"Front-door log","doc.buzz.doors.note":"Every fob use and every release of the door is recorded electronically.","doc.buzz.doors.col.0":"Time","doc.buzz.doors.col.1":"Event","doc.buzz.doors.col.2":"Fob","doc.buzz.doors.foot":"Fobs are issued to residents and the caretaker only. Visitors are buzzed in from inside a flat.","cell.ev.fobout":"Fob out","cell.ev.fobbase":"Basement door, fob in","cell.ev.buzzed":"Front door released from the Apt 7 intercom","cell.ev.exit":"Front door opened from inside","cell.ev.fobin":"Fob in","cell.fob.noor":"N. Haddad (Apt 6)","cell.fob.mateo":"M. Reyes (caretaker)","cell.fob.none":"—","board.leave.title":"The lobby camera and the clock","board.leave.ask":"The lobby camera's clock is not to be trusted. When did the visitor really leave the building?","doc.leave.camera.title":"Lobby camera","doc.leave.camera.note":"The front door and the stairs, as the camera stamps them. The clock was last set after the January blackout.","doc.leave.camera.frame.0":"A figure crosses the street toward the door with a folded newspaper page held over the head against the rain.","doc.leave.camera.frame.1":"At the door. The intercom light blinks. The page is crumpled in one hand, the hood goes up.","doc.leave.camera.frame.2":"In the lobby, head down. Something small is dropped into the bin by the stairs.","doc.leave.camera.frame.3":"Leaving in a hurry, a roll of papers under one arm.","doc.leave.camera.foot":"The camera looks down from above: faces never show.","doc.leave.log.title":"Front-door log (extract)","doc.leave.log.note":"Two entries of the door controller's own record.","doc.leave.log.col.0":"Time","doc.leave.log.col.1":"Event","doc.leave.log.col.2":"Fob","doc.leave.log.foot":"The controller's clock is synced to the exchange, like the meter's.","board.leave.opt.cam":"22:15","board.leave.opt.cam.wrong":"That is only what the camera stamps. The camera showed the intercom blinking at 21:47; the log has that release at 21:53.","board.leave.opt.back":"22:09","board.leave.opt.back.wrong":"Wrong direction. The camera runs behind, so the real time is later than its stamp, not earlier.","board.leave.opt.real":"22:21","board.leave.opt.over":"22:27","board.leave.opt.over.wrong":"Too far. The camera is six minutes behind, not twelve.","board.figure.title":"The height marks","board.figure.ask":"The visitor at the door measures about 185 cm against the marks. Allow 5 cm either way for the hood and the camera angle. Who could be that tall?","board.figure.none":"Select at least one person. Compare the marks with the heights table.","board.figure.wrong.daniel":"188 cm barefoot, about 190 in shoes: at the top of the range, still inside it.","board.figure.wrong.mateo":"182 cm, about 184 in shoes. He fits the marks.","board.figure.wrong.sofia":"170 cm looks too short, but the visitor log says \"very high heels, c. 12 cm\". That makes her about 182. She fits.","board.figure.wrong.noor":"165 cm, about 167 in shoes. Far too short, even with the camera's margin.","doc.figure.marks.title":"Door marks","doc.figure.marks.note":"Marks beside the door run from 150 to 200 cm; the long ones are 160, 180 and 200. The hooded figure's head reaches about the 185 line.","doc.figure.marks.frame.0":"The hooded visitor stands against the marks at the door.","doc.figure.marks.foot":"The camera is fixed above the door, so the marks and the figure are in one picture.","doc.figure.heights.title":"Heights on file","doc.figure.heights.note":"From driving licences and tenant forms, measured without shoes.","doc.figure.heights.col.0":"Name","doc.figure.heights.col.1":"Height (cm)","doc.figure.heights.foot":"Shoes add about 2 cm; heels add their own height. The desk clerk noted what visitors wore.","board.boiler.title":"The basement camera","board.boiler.ask":"Camera 2 runs all night and its clock matches the meter. Mateo's statement, the sheet and the camera disagree after 22:20. Who is on camera at 22:04, the minute the lamp circuit tripped?","board.boiler.wrong.daniel":"Daniel is not in any of these pictures.","board.boiler.wrong.sofia":"Sofia is not in any of these pictures.","board.boiler.wrong.noor":"Noor is not in any of these pictures.","doc.boiler.camera.title":"Basement camera 2","doc.boiler.camera.note":"The boiler corner. The camera records continuously and shows the time.","doc.boiler.camera.frame.0":"Mateo at the boiler with a wrench, the service panel open.","doc.boiler.camera.frame.1":"The same corner. Mateo is still there, wrench in hand.","doc.boiler.camera.frame.2":"Mateo packing up near the boiler.","doc.boiler.camera.foot":"Nobody else comes into the picture between 21:40 and 22:20.","doc.boiler.sheet.title":"Boiler service sheet","doc.boiler.sheet.note":"Filled in by the caretaker for each service.","doc.boiler.sheet.col.0":"Item","doc.boiler.sheet.col.1":"Entry","doc.boiler.sheet.foot":"The burner stays off while the panel is open.","cell.sheet.job":"Job","cell.sheet.jobv":"Annual boiler service","cell.sheet.start":"Started","cell.sheet.end":"Finished","cell.sheet.sign":"Signed","board.paper.title":"The soaked page","board.paper.ask":"The visitor dropped a soaked newspaper page in the lobby bin. Where did it come from?","doc.paper.soaked.title":"Soaked page","doc.paper.soaked.note":"The top of a page, printed THE LYRA GAZETTE, Guest Edition, Saturday. A water stain has run through the weather column.","doc.paper.soaked.frame.0":"The page from the bin, the stain over the weather column.","doc.paper.soaked.foot":"It was crumpled in one hand at the door and dropped in the bin by the stairs.","doc.paper.back.title":"Back of the page","doc.paper.back.note":"Small print: \"Complimentary. Slipped under every guest-room door at 18:00. Not for sale.\"","doc.paper.back.frame.0":"The small print on the back of the page.","doc.paper.back.foot":"Printed for one hotel only.","board.paper.opt.resident":"A resident of Orange Grove Court","board.paper.opt.resident.wrong":"The residents get the building's own \"Orange Grove Notices\". The Gazette is printed for one hotel.","board.paper.opt.guest":"A guest at the Hotel Lyra","board.paper.opt.shop":"Someone from a newsagent","board.paper.opt.shop.wrong":"It is not for sale anywhere.","board.paper.opt.bank":"The bank courier","board.paper.opt.bank.wrong":"The courier left at 17:46. The Gazette was delivered to rooms at 18:00.","board.bar.title":"The hotel cameras and records","board.bar.ask":"Daniel's tab was paid at 22:10 on his card, and he says he was at the bar. Who actually paid it?","board.bar.wrong.daniel":"The receipt carries Daniel's name, but look at the bar camera: he is not in the picture. A receipt only proves that a card was used.","board.bar.wrong.noor":"Noor was nowhere near the hotel.","board.bar.wrong.mateo":"Mateo was in the basement of Orange Grove Court that night.","doc.bar.cameras.title":"Hotel cameras","doc.bar.cameras.note":"Reception, the bar and the breakfast room.","doc.bar.cameras.frame.0":"Daniel and Sofia check in together at reception.","doc.bar.cameras.frame.1":"Sofia sits alone at the bar. Two glasses stand in front of her.","doc.bar.cameras.frame.2":"At the bar a woman pays the tab with a card. The barman waits.","doc.bar.cameras.frame.3":"Daniel eats breakfast alone.","doc.bar.cameras.foot":"These are the only cameras the hotel has. The corridors, the car park and the side door have none.","doc.bar.records.title":"Hotel and phone records","doc.bar.records.note":"Key card, TV system, receipts and the phone company.","doc.bar.records.col.0":"Time","doc.bar.records.col.1":"Event","doc.bar.records.col.2":"Source","doc.bar.records.foot":"Hotel Lyra to Orange Grove Court: 60 minutes by car, each way.","cell.rec.open214":"Room 214 door opened","cell.rec.filmstart":"Room 214 TV: film started","cell.rec.mast":"Phone connected to the hotel mast, all night","cell.rec.tab":"Bar tab, 2 drinks, card D. HART","cell.rec.filmend":"Room 214 TV: film ended","cell.src.key":"Key card","cell.src.tv":"TV system","cell.src.mast":"Phone company","cell.src.receipt":"Receipt","board.door.title":"The evacuation plan and the sensors","board.door.ask":"Someone left the hotel and came back unseen. Which exit could they have used so that no camera caught them?","doc.door.plan.title":"Hotel plan","doc.door.plan.note":"The evacuation plan on the corridor wall. Room 214 is next to the service stairs.","doc.door.plan.col.0":"Exit","doc.door.plan.col.1":"Route","doc.door.plan.col.2":"Camera","doc.door.plan.col.3":"Opens","doc.door.plan.foot":"Only the main entrance and the bar terrace are watched.","cell.ex.main":"Main entrance","cell.exd.main":"Past reception","cell.cam.reception":"Reception camera","cell.op.free":"Free","cell.ex.terrace":"Bar terrace door","cell.exd.terrace":"Through the bar","cell.cam.bar":"Bar camera","cell.ex.side":"Side door","cell.exd.side":"Service stairs to the alley","cell.cam.none":"None","cell.op.inside":"Free from inside","cell.ex.lift":"Car park lift","cell.exd.lift":"Down to the car park","cell.op.card":"Room key card","doc.door.sensors.title":"Sensors and logs","doc.door.sensors.note":"What the building records without cameras.","doc.door.sensors.col.0":"Time","doc.door.sensors.col.1":"Event","doc.door.sensors.foot":"The sensor records openings, not names. The lift logs every key card use.","cell.sn.open":"Side door opened","cell.sn.tonight":"Tonight","cell.sn.lift":"Car park lift: no entries","board.door.opt.main":"Main entrance","board.door.opt.main.wrong":"It runs past the reception camera. Nobody leaves unseen that way.","board.door.opt.terrace":"Bar terrace door","board.door.opt.terrace.wrong":"It opens inside the bar camera's view.","board.door.opt.side":"Side door","board.door.opt.lift":"Car park lift","board.door.opt.lift.wrong":"The lift needs a key card, and its log has no entries tonight.","board.timing.title":"The timeline strip","board.timing.ask":"Between the two side-door openings, at most how many minutes could the unseen person have spent at Orange Grove Court?","doc.timing.sensor.title":"Side-door sensor","doc.timing.sensor.note":"The two openings of the side door that night.","doc.timing.sensor.col.0":"Time","doc.timing.sensor.col.1":"Event","doc.timing.sensor.foot":"Driving takes 60 minutes each way.","doc.timing.stay.title":"Visitor's stay","doc.timing.stay.note":"The two door-controller entries of the visitor at Orange Grove Court.","doc.timing.stay.col.0":"Time","doc.timing.stay.col.1":"Event","doc.timing.stay.col.2":"Fob","doc.timing.stay.foot":"The lobby camera runs six minutes slow.","board.timing.opt.zero":"0","board.timing.opt.zero.wrong":"152 minutes away is more than the 120 minutes of driving.","board.timing.opt.thirtytwo":"32","board.timing.opt.ninetytwo":"92","board.timing.opt.ninetytwo.wrong":"You counted only one drive. The trip is there and back.","board.timing.opt.all":"152","board.timing.opt.all.wrong":"That is the whole time away, driving included.","board.torn.title":"The torn page","board.torn.ask":"Does the soaked page from the lobby bin belong to the Gazette in room 214?","doc.torn.page.title":"Two torn edges","doc.torn.page.note":"The soaked page has a torn edge. Room 214's Gazette has lost its first page. Turn the page and try the fit.","doc.torn.page.foot":"Torn paper keeps its edge: only the page it came from will fit.","board.torn.opt.yes":"Yes, it belongs to that Gazette","board.torn.opt.no":"No, it is a different paper","board.torn.opt.no.wrong":"Try the fit: the torn edges mesh. It is the same page.","board.signature.title":"Two signatures","board.signature.ask":"Compare the two signatures through the magnifier. Find at least three differences.","doc.signature.sigs.title":"Priya's sample and the guarantee","doc.signature.sigs.note":"On the left her sample signature. On the right the signature on the loan guarantee.","doc.signature.sigs.foot":"A signature is made quickly and the same way every time.","board.signature.spot.leg":"The leg of the R is stretched on the guarantee.","board.signature.spot.dot":"The dot of the i floats higher and to the side.","board.signature.spot.pen":"The pen pressed much harder on the guarantee.","board.signature.spot.stamp":"Her potter's stamp is missing on the guarantee.","board.tiles.title":"Glaze test tiles","doc.tiles.tiles.title":"Test tiles","doc.tiles.tiles.note":"Five small tiles on the shelf, each glazed a different colour, each stamped on the back.","doc.tiles.tiles.frame.0":"Tile 1: tomato-red glaze. A square is stamped on the back.","doc.tiles.tiles.frame.1":"Tile 2: ochre-yellow glaze. A circle is stamped on the back.","doc.tiles.tiles.frame.2":"Tile 3: celadon-green glaze. A triangle is stamped on the back.","doc.tiles.tiles.frame.3":"Tile 4: cobalt-blue glaze. A star is stamped on the back.","doc.tiles.tiles.frame.4":"Tile 5: black and blistered. A cross is stamped on the back.","doc.tiles.tiles.foot":"The stamps are Priya's own pottery marks.","board.kiln.title":"Kiln notebook","doc.kiln.chart.title":"Kiln notebook","doc.kiln.chart.note":"Priya's firing notes, in pencil, with a glaze chart on the last page.","doc.kiln.chart.col.0":"Glaze","doc.kiln.chart.col.1":"Cone","doc.kiln.chart.foot":"Cones below 1 are written with a zero. 06 is cooler than 04.","cell.gl.red":"Tomato red","cell.gl.yellow":"Ochre yellow","cell.gl.green":"Celadon green","cell.gl.blue":"Cobalt blue","cell.gl.black":"Black, blistered","cell.gl.discard":"overfired, discard","int.noor.name":"Noor Haddad","int.noor.q1.ask":"What was Priya doing when you knocked?","int.noor.q1.answer":"She stood at the table, glasses pushed up, a little magnifier in one hand and [[two signatures side by side]]. She didn't ask me in. She said the kiln stays, and closed the door.","int.noor.q1.p1.note":"Noor: at 19:30 Priya was comparing two signatures with a magnifier.","int.noor.q2.ask":"Did you hear anything before you knocked?","int.noor.q2.answer":"Through the wall, yes. A woman's voice, raised. \"[[You'll regret this.]]\" That's the line I caught. Then [[the heels went down the stairs]], quick, like someone late for a train.","int.noor.q2.p1.note":"Noor heard a woman say \"you'll regret this\".","int.noor.q2.p2.note":"Then heels went down the stairs.","int.noor.q3.ask":"And the rest of the night?","int.noor.q3.answer":"On the ward from 20:10 until 06:20. Ask the hospital. I saw nothing here after I left.","int.mateo.name":"Mateo Reyes","int.mateo.q1.ask":"Did anything unusual arrive for Apartment 7 on Saturday?","int.mateo.q1.answer":"A courier, 17:40. [[A bank envelope]], Guarantee Department, red stamp, signature required. I took it up myself. She opened it right there at her door. [[She went white.]] Then she said, \"Monday at nine, then.\" Not to me.","int.mateo.q1.p1.note":"Mateo: a bank envelope (Guarantee Dept.) came for Priya at 17:40.","int.mateo.q1.p2.note":"Priya opened it at her door at 17:44 and went white.","int.mateo.q2.ask":"Your statement says quarter to eleven. The sheet says 22:35.","int.mateo.q2.answer":"[[I fill the sheet in before I start]]. Boiler jobs take an hour, so I write the hour. The rest was mopping up. Camera has me packing up by 22:20, if you want to look.","int.mateo.q2.p1.note":"Mateo: writes the finish time on service sheets in advance.","int.mateo.q3.ask":"Tell me about the lobby camera.","int.mateo.q3.answer":"Old thing. Been behind since the January blackout. Nobody fixed it.","int.barman.name":"Barman","int.barman.q1.ask":"Tell me about the woman who paid the tab.","int.barman.q1.answer":"Hard to miss. Heels so high you heard her coming across the marble. She looked me [[straight in the eye]], and I'm [[one-eighty-two]].","int.barman.q1.p1.note":"Barman: the woman wore very high heels.","int.barman.q1.p2.note":"At 182 cm the barman was eye to eye with her.","int.barman.q2.ask":"What time was that?","int.barman.q2.answer":"Ten, thereabouts. Maybe half past. I don't watch clocks. The register does, and the cameras in the back office do. [[The key's on the hook by the till.]]","int.barman.q3.ask":"Who was she with?","int.barman.q3.answer":"Nobody at the bar. Two drinks poured, [[one stayed full]]. She said, \"He'll be along.\" He never came down.","int.barman.q3.p1.note":"Barman: she waited for someone who never came down; one drink stayed full.","int.sofia.q1.ask":"A neighbour heard you say \"you'll regret this\".","int.sofia.q1.answer":"I did. [[Daniel told me the studio was pledged for a loan.]] If the settlement went ahead, the bank would call it in and everyone would lose, Priya too. I told her she'd regret it. I meant money. I didn't mean anything else.","int.sofia.q1.p1.note":"Sofia: Daniel had told her the studio was pledged for a loan; she meant financial regret.","int.sofia.q2.ask":"What did you see on the table?","int.sofia.q2.answer":"The folder, and on top of it [[a bank envelope with a red stamp]]. I mentioned it to Daniel in the car. He went quiet. I thought he was tired.","int.sofia.q2.p1.note":"Sofia: told Daniel in the car about the bank envelope; he went quiet.","int.sofia.q3.ask":"Why did you pay with Daniel's card?","int.sofia.q3.answer":"He asked me to wait at the bar from half past nine and pay [[at ten sharp]] with his card if he wasn't down. He said he'd be in the room with a film and a call. He's never been that particular about a tab.","int.sofia.q3.p1.note":"Sofia: Daniel told her to pay \"at ten sharp\" with his card; he said he'd be in the room.","conf.daniel.A.say":"\"I haven't been near Orange Grove Court since Priya moved in.\"","conf.daniel.A.broken":"\"A page of the hotel's own paper in her lobby bin. Anyone could have carried it there.\" He swallows. \"Not me.\"","conf.daniel.B.say":"\"I had a drink at the bar around ten and went up to my room.\"","conf.daniel.B.broken":"\"Sofia paid. That's... she was doing me a favour.\" A pause. \"I wasn't there. Fine.\"","conf.daniel.C.say":"\"I was in that hotel all night.\"","conf.daniel.C.broken":"\"A side door that nobody sees. You can't prove it was me.\" His voice drops. \"You can't.\"","conf.daniel.finale":"\"I only went to get the folder back. She had the bank's letter, the guarantee. I told her I could explain. She poured tea.\" He breathes out. \"She said she'd listen. Then she said she wouldn't. I pushed her, I didn't mean… and then she was on the floor and I was looking for the folder.\"","conf.daniel.finale.forgery":"\"The signature. You found it, didn't you.\"","container.lobby:doorcontroller.title":"The door controller","container.lobby:doorcontroller.hint":"The building's door controller. It can print the front-door record for any time you choose.","container.lobby:doorcontroller.blank":"The printer hums and prints a blank strip: nothing recorded near that time.","hot.lobby.doorcontroller.label":"Door controller","hot.lobby.doorcontroller.say":"The building's door controller. It can print the front-door record for any time you choose.","needs.controller":"The screen asks for a time. You have no reason to pick one yet.","container.living:tvunit.title":"The TV cabinet lock","container.living:tvunit.hint":"Four little pottery stamps hold the cabinet shut. A note is stuck on the door: \"Load as the kiln climbs.\"","container.living:tvunit.wrong":"The stamps click, then stick. Try again in a moment.","container.living:tvunit.paperTitle":"Two papers from the cabinet","container.living:tvunit.paper":"(1) A copy of a loan guarantee for 80,000, pledging the studio and the kiln, signed P. Raman. (2) A note in Priya's hand: \"This is not my signature. If D. explains, I will listen. If not: bank, Monday 9:00.\"","container.living:tvunit.open":"The cabinet swings open. The two papers lie inside.","hot.living.tiles.label":"Glaze test tiles","hot.living.tiles.say":"Five small tiles on the shelf, each glazed a different colour, each stamped on the back.","hot.basement.shelfunit.label":"Moving boxes","hot.basement.shelfunit.say":"Moving boxes marked STUDIO. One holds a kiln notebook.","item.basementkey.name":"Basement key","item.basementkey.text":"a brass key with a tag: Boiler room","find.lobby.rug":"You lift the corner of the lobby rug. A brass key lies underneath, with a paper tag: 'Boiler room'. Somebody has been hiding it from the draught.","gate.lobby.basement":"The basement door is locked. A small tag on the lock says 'Boiler room'. The caretaker must keep the key somewhere safe.","item.backofficekey.name":"Back-office key","item.backofficekey.text":"a small key on a green tag: Office","needs.office":"The monitor is in the back office. The door is locked.","item.mastercard.name":"Master card","item.mastercard.text":"a white card: Rooms, second floor","gate.hcorr.room214":"Room 214 is locked. You need a master card.","call.hq.phone.none":"No reason to call anyone yet.","call.hq.phone.0":"The hotel manager agrees to let you in.","call.hq.phone.1":"The manager will send up a master card for room 214.","hint.0.a":"Switch on the difference finder in the living room and compare Noor's visit with the morning.","hint.0.b":"Tap the lamp, the slippers, the cups and the table. At least three things changed.","hint.1.a":"The building keeps an electricity meter for every flat. Where would it be?","hint.1.b":"Downstairs. The basement door is locked. Where would a caretaker keep a spare?","hint.2.a":"Who gets into the building without a key fob?","hint.2.b":"The door controller on the lobby desk will print the record for a time you choose. Which minutes matter?","hint.3.a":"The lobby monitor shows the visitor dropping something. Where would it end up?","hint.3.b":"Look at the third frame, then check the bin by the stairs.","hint.4.a":"The page came from a hotel. A call from headquarters might open a door.","hint.4.b":"Go to the detective's office and use the telephone.","hint.5.a":"Daniel says he was in the hotel bar. Who can tell you what the bar saw?","hint.5.b":"Talk to the barman and read his sentences closely.","hint.6.a":"Sofia is cleared, yet somebody left the hotel. How could they do it unseen?","hint.6.b":"Study the plan in the second-floor corridor and the sensor log.","hint.7.a":"You have what you need. Open the accusation tab.","hint.7.b":"Each wrong answer is contradicted by one of your facts. Check the notebook.","accuse.who.sofia.why":"Sofia paid at the hotel bar at 22:10, an hour's drive from here.","accuse.who.noor.why":"Noor has a fob and would never need buzzing in. The visitor had none.","accuse.who.mateo.why":"Mateo has a fob and was in the building already. The visitor had none.","accuse.how.guest.label":"A guest she let in, who pushed her during an argument","accuse.how.burglar.label":"A burglar she surprised in the flat","accuse.how.burglar.why":"Nothing was taken except the settlement folder, and a burglar does not stay to drink tea.","accuse.how.fall.label":"She fell alone","accuse.how.fall.why":"Someone was buzzed in at 21:53. She was not alone.","accuse.why.forgery.label":"To bury the forged guarantee before Monday","accuse.why.jealousy.label":"Jealousy over Daniel","accuse.why.jealousy.why":"Jealousy does not take away the settlement folder. The folder is the point.","accuse.why.lease.label":"A dispute over the lease and the kiln","accuse.why.lease.why":"A neighbour or the caretaker would not have needed buzzing in. The visitor came from outside.","verdict.truth.0.when":"17:44","verdict.truth.0.text":"A bank envelope reaches Priya. She opens it at her door and goes white.","verdict.truth.1.when":"19:25","verdict.truth.1.text":"Sofia leaves after a heated talk and mentions the envelope to Daniel in the car.","verdict.truth.2.when":"20:35","verdict.truth.2.text":"Daniel and Sofia check in at the Lyra. It is the last time a camera sees Daniel until morning.","verdict.truth.3.when":"20:50","verdict.truth.3.text":"Daniel leaves by the side door, his phone in the room, a film running, and drives sixty minutes.","verdict.truth.4.when":"21:53","verdict.truth.4.text":"Priya buzzes him in and makes tea for two.","verdict.truth.5.when":"22:04","verdict.truth.5.text":"The talk fails. He pushes her, the lamp cord is pulled and she falls.","verdict.truth.6.when":"22:10","verdict.truth.6.text":"In the hotel bar, Sofia pays the tab with Daniel's card because he asked her to, with no idea why.","verdict.truth.7.when":"22:21","verdict.truth.7.text":"He leaves with the folder and a soaked page of the hotel's paper in the lobby bin behind him.","verdict.truth.8.when":"23:22","verdict.truth.8.text":"He slips back in by the side door. In the morning he has breakfast on camera.","room.hq":"Detective's office","room.interrog":"Interview room","room.hlobby":"Hotel lobby and bar","room.hcorr":"Second-floor corridor","room.room214":"Room 214","ui.msg.enter.living":"Back in Priya's living room. Two cups on the table, and a magnifier by the folder's place.","ui.msg.enter.lobby":"The lobby. A desk with a door controller and a monitor, height marks by the door and a bin by the stairs.","ui.msg.enter.basement":"The basement: boiler, workbench, the building's electricity meter and a second camera screen.","ui.msg.enter.hq":"The detective's office: a telephone, a case board on the wall and a strip of tape marked in minutes.","ui.msg.enter.interrog":"The interview room is next door: a table, two chairs, a lamp and a one-way glass.","ui.msg.enter.hlobby":"The Hotel Lyra's lobby: a reception desk, a rack of Gazettes and a long bar with a barman polishing a glass.","ui.msg.enter.hcorr":"The second-floor corridor: an evacuation plan, a fire door and room 214.","ui.msg.enter.room214":"Room 214: a bed hardly slept in, a TV on its menu and a Gazette with its front page torn off.","hot.lobby.bin.label":"Bin","hot.lobby.bin.say":"A rubbish bin by the stairs. Something soaked sits on top.","hot.lobby.doormarks.label":"Height marks","hot.lobby.doormarks.say":"Pencil marks beside the door, 150 to 200 cm.","hot.living.magnifier.label":"Magnifier","hot.living.magnifier.say":"A small folding magnifier lies by the folder.","hot.living.cornertable.label":"Table corner","hot.living.cornertable.say":"A scuffed corner of the table.","hot.hq.corkboard.label":"Case board","hot.hq.corkboard.say":"Everything you know, pinned up.","hot.hq.phone.label":"Telephone","hot.hq.phone.say":"The detective's telephone. A phone book lies beside it.","hot.hq.board.label":"Timeline strip","hot.hq.board.say":"A strip of tape across the wall, marked in minutes.","hot.interrog.glass.label":"One-way glass","hot.interrog.glass.say":"A one-way glass. Somebody on the other side may be watching.","hot.interrog.chair.label":"Chair","hot.interrog.chair.say":"The chair across the table. Whoever sits here has to talk.","hot.interrog.recorder.label":"Recorder","hot.interrog.recorder.say":"A recorder with two reels.","hot.interrog.table.label":"Table","hot.interrog.table.say":"A bare table under a hanging lamp.","hot.hlobby.monitor.label":"Security monitor","hot.hlobby.monitor.say":"The hotel's three cameras on one screen.","hot.hlobby.bar.label":"Bar","hot.hlobby.bar.say":"A long bar with bottles shelved to the ceiling. The barman polishes a glass.","hot.hlobby.office.label":"Back office","hot.hlobby.office.say":"A door marked Staff.","hot.hlobby.rack.label":"Gazette rack","hot.hlobby.rack.say":"A rack of this evening's Gazette, \"Guest Edition\". Complimentary.","hot.hlobby.till.label":"Till","hot.hlobby.till.say":"The till. Tapes and receipts, filed by minute.","hot.hcorr.plan.label":"Evacuation plan","hot.hcorr.plan.say":"Exits marked in green.","hot.hcorr.sidedoor.label":"Side door","hot.hcorr.sidedoor.say":"A fire door with a little sensor box. It logs each opening, not who.","hot.hcorr.door212.label":"Room 212","hot.hcorr.door212.say":"Room 212. Somebody's room: do not disturb.","hot.room214.phone.label":"Phone","hot.room214.phone.say":"A phone on the bedside table, face down. No missed calls.","hot.room214.tv.label":"TV","hot.room214.tv.say":"The TV is on its menu. The film ended long ago.","hot.room214.bin.label":"Wastepaper bin","hot.room214.bin.say":"A Gazette with its front page torn off.","hot.room214.gazette.label":"Gazette","hot.room214.gazette.say":"Tonight's Gazette lies on the desk.","hot.room214.bed.label":"Bed","hot.room214.bed.say":"A bed that has hardly been slept in.","hot.room214.table.label":"Desk","hot.room214.table.say":"Hotel stationery and a pen.","hot.lobby.monitor.label":"Lobby monitor","hot.lobby.monitor.say":"The front-door camera.","hot.hlobby.stool.label":"Bar stool","hot.hlobby.stool.say":"A leather bar stool, still warm."}};
